/**
 * CONTROLLED PRODUCTION CONTAMINATION RECOVERY SCRIPT
 *
 * Requirements:
 * 1. Plan mode must be strictly read-only (--plan).
 * 2. Apply mode must require ALL of:
 *    - APPLY_PRODUCTION_RECOVERY=true
 *    - EXPECTED_FIREBASE_PROJECT_ID=gen-lang-client-0195097895
 *    - EXPECTED_FIRESTORE_DATABASE_ID=ai-studio-efluz-4c6c88a6-697e-4fdf-82ed-45fec68ca34d
 *    - RECOVERY_PLAN_HASH=<hash generated by plan mode>
 * 3. Before applying, re-read every affected document and compare its content hash with the plan.
 * 4. Back up every affected document before modification (locally and under recovery_backups/<runId>/documents).
 * 5. Use Firestore batches of at most 400 operations.
 * 6. Never perform a full collection delete.
 * 7. Never delete audit logs.
 * 8. Add one new audit log with actorUserId: 'system-recovery-2026-09-14'.
 */

import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import { initializeFirebaseAdmin, getFirebaseStatus, getFirestoreDb } from '../firebase/admin';
