const SEASON_ID = 'season-2026-27';

interface DocumentState {
  collection: string;
  docId: string;
  path: string;
  exists: boolean;
  data: any;
  contentHash: string;
}

interface PlannedOperation {
  op: 'delete' | 'set' | 'update';
  collection: string;
  docId: string;
  path: string;
  payload?: any;
  currentData: any;
  exists: boolean;
  contentHash: string;
  reason: string;
}

interface RecoveryPlan {
  projectId: string;
  databaseId: string;
  seasonId: string;
  generatedAt: string;
  planHash: string;
  candidateResolutions: {
    arsenal: any;
    sunderland: any;
  };
  operations: PlannedOperation[];
}

function computeHash(obj: any): string {
  const str = JSON.stringify(obj || null, Object.keys(obj || {}).sort());
  return crypto.createHash('sha256').update(str).digest('hex');
}

async function fetchDocumentState(db: any, collection: string, docId: string): Promise<DocumentState> {
  const docRef = db.collection(collection).doc(docId);
  const snap = await docRef.get();
  const exists = snap.exists;
  const data = exists ? snap.data() : null;
  return {
    collection,
    docId,
    path: `${collection}/${docId}`,
    exists,
    data,
    contentHash: computeHash(data),
  };
}

